class Cart:
    def __init__(self):
        self.items = {}

    def add(self, sku, qty=1):
        if qty < 1:
            raise ValueError("quantity must be positive")
        self.items[sku] = self.items.get(sku, 0) + qty

    def total_items(self):
        return sum(self.items.values())

