import unittest

from shop.cart import Cart


class CartTest(unittest.TestCase):
    def test_add(self):
        cart = Cart()
        cart.add("a", 2)
        self.assertEquals(cart.total_items(), 2)

    def test_rejects_zero(self):
        with self.assertRaisesRegexp(ValueError, "positive"):
            Cart().add("a", 0)

    def test_not_empty_after_add(self):
        cart = Cart()
        cart.add("a")
        self.assertNotEquals(cart.total_items(), 0)

    def test_new_cart_is_empty(self):
        self.assert_(Cart().total_items() == 0)
